-- CP4 CHECK (phase 1m-8 B9b): every row must be true
select 'cp.census still SECURITY DEFINER with a fixed search_path, cp_lookup may run it, PUBLIC may not' as what,
  exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'cp' and p.proname = 'census' and p.prosecdef and p.proconfig::text like '%search_path=pg_catalog, pg_temp%') and has_function_privilege('cp_lookup', 'cp.census(jsonb)', 'execute') and not has_function_privilege('public', 'cp.census(jsonb)', 'execute') as ok
union all select 'the census carries by_package with the eight keys and six packages + none + unknown in packages', (select count(*) = 8 from jsonb_object_keys(cp.census('{}'::jsonb)->'by_package')) and (select count(*) = 8 from jsonb_object_keys(cp.census('{}'::jsonb)->'packages'))
union all select 'package counts add up to the companies and per-package parts add up to the whole', (select sum(v::int) from jsonb_each_text(cp.census('{}'::jsonb)->'packages') e(k, v)) = (cp.census('{}'::jsonb)->>'companies')::int and (select sum((v->>'companies')::int) from jsonb_each(cp.census('{}'::jsonb)->'by_package') e(k, v)) = (cp.census('{}'::jsonb)->>'companies')::int
union all select 'the six packages are valid limit keys, an unknown key is refused', cp.census('{"business_premium": 7000, "business_max": 1}'::jsonb) is not null and cp.census('{"evil":1}'::jsonb) is null
union all select 'the census holds no company id, e-mail or money word', cp.census('{}'::jsonb)::text !~* '([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|@|amount|price|currency|invoice)'
union all select 'the function is commented', obj_description('cp.census(jsonb)'::regprocedure, 'pg_proc') is not null;
